import numpy as np

def forward_euler(f, y0, t0, t1, h):
    ts, ys = [t0], [np.array(y0, dtype=float)]
    while ts[-1] < t1 - 1e-15:
        y, t = ys[-1], ts[-1]
        ys.append(y + h * f(t, y))
        ts.append(t + h)
    return np.array(ts), np.array(ys)

