def bisect(f, lo, hi, tol=1e-12, max_iter=200):
    flo = f(lo)
    if flo * f(hi) > 0:
        raise ValueError("no sign change in bracket")
    for _ in range(max_iter):
        mid = (lo + hi) / 2
        fm = f(mid)
        if abs(fm) < tol or hi - lo < tol:
            return mid
        if flo * fm < 0:
            hi = mid
        else:
            lo, flo = mid, fm
    return (lo + hi) / 2

