def newton(f, df, x0, tol=1e-14, max_iter=100):
    x = x0
    for step in range(max_iter):
        fx = f(x)
        if abs(fx) < tol:
            return x, step
        dx = fx / df(x)
        x -= dx
        if abs(dx) < tol * max(1.0, abs(x)):
            return x, step
    return x, max_iter

root, steps = newton(lambda x: x ** 2 - 2, lambda x: 2 * x, 1.0)
print(f"{root:.15f}", steps, f"{root ** 2 - 2:.2e}")

def secant(f, x0, x1, tol=1e-13, max_iter=100):
    f0, f1 = f(x0), f(x1)
    for _ in range(max_iter):
        if abs(f1 - f0) < 1e-300:
            break
        x2 = x1 - f1 * (x1 - x0) / (f1 - f0)
        x0, x1, f0, f1 = x1, x2, f1, f(x2)
        if abs(f1) < tol:
            break
    return x1

def fixed_point(g, x0, tol=1e-13, max_iter=1000):
    x = x0
    for _ in range(max_iter):
        nxt = g(x)
        if abs(nxt - x) < tol:
            return nxt
        x = nxt
    return x

