import numpy as np

def steady_state_power(P, iters=10000):
    v = np.full(len(P), 1.0 / len(P))
    for _ in range(iters):
        v = v @ P
    return v

def steady_state_eig(P):
    vals, vecs = np.linalg.eig(P.T)
    v = np.real(vecs[:, np.argmin(np.abs(vals - 1))])
    return v / v.sum()

P = np.array([[0.9, 0.1, 0.0], [0.2, 0.7, 0.1], [0.1, 0.3, 0.6]])
a, b = steady_state_power(P), steady_state_eig(P)
print(a.round(5), np.allclose(a, b, atol=1e-6), round(a.sum(), 12))

import math

def poisson_log_lik(data, lam):
    if lam <= 0:
        return -math.inf
    return sum(x * math.log(lam) - lam - math.lgamma(x + 1) for x in data)

def mle_poisson(data, lo=1e-6, hi=100.0, iters=200):
    for _ in range(iters):
        m1, m2 = lo + (hi - lo) / 3, hi - (hi - lo) / 3
        if poisson_log_lik(data, m1) < poisson_log_lik(data, m2):
            lo = m1
        else:
            hi = m2
    return (lo + hi) / 2

data = [2, 3, 1, 4, 2, 0, 3, 2, 5, 2]
print(round(mle_poisson(data), 6), round(sum(data) / len(data), 6))
